status=0
node "$SELECTOR" --run production-schema --root candidate || status=$?
if [ -f "$RUNNER_TEMP/production-schema-report.json" ]; then
  node -e 'const r=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8"));
    const lines=["### migration-verify: "+r.status,"",...r.errors.map(e=>"- error: `"+e+"`"),
      "- pending migrations: "+((r.pending||[]).join(", ")||"none"),
      "- repository-only columns and functions (tests see them, production does not): "+((r.repository_only||[]).length)];
    require("fs").appendFileSync(process.env.GITHUB_STEP_SUMMARY, lines.join("\n")+"\n");' "$RUNNER_TEMP/production-schema-report.json"
fi
exit $status

set -euo pipefail
case "$EVENT_NAME" in
  pull_request)
    base=$PR_BASE head=$PR_HEAD
    test "$(git rev-parse --verify --quiet "$GITHUB_SHA^2")" = "$head" ;;
  push) base=$PUSH_BASE head=$GITHUB_SHA ;;
  workflow_dispatch) head=$GITHUB_SHA base=$(git merge-base origin/main "$GITHUB_SHA") ;;
  *) echo "::error::no changed range for event $EVENT_NAME"; exit 1 ;;
esac
for sha in "$base" "$head"; do
  [[ "$sha" =~ ^[0-9a-f]{40}$ && ! "$sha" =~ ^0+$ ]] || { echo "::error::not a commit id: '$sha'"; exit 1; }
done
echo "base=$base" >> "$GITHUB_OUTPUT"
echo "head=$head" >> "$GITHUB_OUTPUT"

set -euo pipefail
case "$EVENT_NAME" in
  pull_request)
    base=$PR_BASE head=$PR_HEAD
    test "$(git rev-parse --verify --quiet "$GITHUB_SHA^2")" = "$head" ;;
  push) base=$PUSH_BASE head=$GITHUB_SHA ;;
  workflow_dispatch) head=$GITHUB_SHA base=$(git merge-base origin/main "$GITHUB_SHA") ;;
  *) echo "::error::no changed range for event $EVENT_NAME"; exit 1 ;;
esac
for sha in "$base" "$head"; do
  [[ "$sha" =~ ^[0-9a-f]{40}$ && ! "$sha" =~ ^0+$ ]] || { echo "::error::not a commit id: '$sha'"; exit 1; }
done
echo "base=$base" >> "$GITHUB_OUTPUT"
echo "head=$head" >> "$GITHUB_OUTPUT"

$ErrorActionPreference = 'Stop'
if ($env:EVENT_NAME -ne 'push') { exit 0 }
if ($env:PUSH_REF -eq 'refs/heads/clued-train/staging') {
  # Checkout fetched full history; no candidate code has run. T is the
  # root of S's member chain (ADR 0019), a commit on main (S^1 for one
  # member), walked by the runner hook's own code read from main.
  $base = node --input-type=module -e "
    const { execFileSync } = await import('node:child_process');
    const hook = execFileSync('git', ['show', 'origin/main:scripts/runner/clued-runner-job-started.mjs']);
    const { stagingBaseFromCheckout } = await import('data:text/javascript;base64,' + hook.toString('base64'));
    process.stdout.write(await stagingBaseFromCheckout(process.env.STAGING_SHA));"
  if ($LASTEXITCODE -ne 0 -or $base -notmatch '^[0-9a-f]{40}$') { exit 1 }
  [System.IO.File]::AppendAllText($env:GITHUB_OUTPUT, "sha=$base`n")
} else {
  $base = git rev-parse "$($env:STAGING_SHA)^1"
  if ($LASTEXITCODE -ne 0 -or $base -notmatch '^[0-9a-f]{40}$') { exit 1 }
}
[System.IO.File]::AppendAllText($env:GITHUB_OUTPUT, "ci_base=$base`n")
